const { AbilityBuilder, Ability } = require('@casl/ability');

function defineAbilityFor(user) {
  const { can, cannot, build } = new AbilityBuilder(Ability);   // deny by default: empty builder
  if (user.roles.includes('pauser')) can('pause', 'Transfers');
  if (user.roles.includes('editor')) can('update', 'Article', { authorId: user.id });
  cannot('delete', 'Article');                                   // explicit deny overrides
  return build();
}

app.post('/transfers/pause', (req, res) => {
  if (!req.ability.can('pause', 'Transfers')) return res.sendStatus(403);   // enforcement
  ...
});
